import http from 'node:http';
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Explorer Fixture</title></head><body>
<header><h1>Fixture desk</h1><p id="roleLabel">Role: Member</p><nav aria-label="Areas"><button id="areaProjects">Projects</button><button id="areaReports">Reports</button><button id="areaSettings">Settings</button></nav></header>
<main id="main"><h2>Workspace overview</h2><p>Choose a synthetic workflow to inspect.</p><button id="roleViewer">Use Viewer role</button><button id="roleMember">Use Member role</button><button id="startWizard">Start deep wizard</button><button id="openDenied">Open admin report</button><button id="openLogin">Open sign-in checkpoint</button><button id="openReports">Open Reports</button><button id="showDuplicate">Show duplicate state</button></main>
<script>
let role='Member';const main=document.querySelector('#main');function roleLabel(){document.querySelector('#roleLabel').textContent='Role: '+role;}
function home(){main.innerHTML='<h2>Workspace overview</h2><p>Choose a synthetic workflow to inspect.</p><button id="roleViewer">Use Viewer role</button><button id="roleMember">Use Member role</button><button id="startWizard">Start deep wizard</button><button id="openDenied">Open admin report</button><button id="openLogin">Open sign-in checkpoint</button><button id="openReports">Open Reports</button><button id="showDuplicate">Show duplicate state</button>';bind();}
function bind(){document.querySelector('#roleViewer')?.addEventListener('click',()=>{role='Viewer';roleLabel();});document.querySelector('#roleMember')?.addEventListener('click',()=>{role='Member';roleLabel();});document.querySelector('#startWizard')?.addEventListener('click',()=>{if(role==='Viewer'){main.innerHTML='<h2>Access denied</h2><p>Record creation is unavailable to the Viewer role in this fixture.</p><button id="goHome">Return to workspace</button>';bind();}else wizard(1);});document.querySelector('#openDenied')?.addEventListener('click',()=>{main.innerHTML='<h2>Access denied</h2><p>Admin report is unavailable to the Viewer role in this fixture.</p><button id="goHome">Return to workspace</button>';bind();});document.querySelector('#goHome')?.addEventListener('click',home);document.querySelector('#openLogin')?.addEventListener('click',()=>{main.innerHTML='<h2>Sign-in checkpoint (synthetic)</h2><p>This fixture pauses exploration for a fake identity handoff. No credentials are requested.</p><button id="fixtureContinue">Continue with fixture identity</button>';bind();});document.querySelector('#fixtureContinue')?.addEventListener('click',()=>{main.innerHTML='<h2>Workspace ready</h2><p>Fixture identity resumed at the member workspace.</p><button id="goHome">Return to workspace</button>';bind();});document.querySelector('#openReports')?.addEventListener('click',()=>{main.innerHTML='<h2>Reports</h2><p>Export a synthetic CSV to exercise asynchronous download handling.</p><button id="prepareExport">Prepare CSV export</button><div id="exportStatus" aria-live="polite"></div><button id="goHome">Return to workspace</button>';bind();document.querySelector('#prepareExport').addEventListener('click',prepareExport);});document.querySelector('#showDuplicate')?.addEventListener('click',()=>{main.innerHTML='<h2>Settings</h2><p>Duplicate state observed for two synthetic rows with the same label.</p><button id="goHome">Return to workspace</button>';bind();});}
function wizard(step){if(step>3){main.innerHTML='<h2>Record created</h2><p>The synthetic wizard completed and displayed its final record summary.</p><button id="goHome">Return to workspace</button>';bind();return;}main.innerHTML='<h2>New record · Step '+step+' of 3</h2><p>'+['Choose a type','Enter a title','Review the synthetic details'][step-1]+'</p><button id="continueWizard">Continue</button><button id="goHome">Cancel</button>';document.querySelector('#continueWizard').addEventListener('click',()=>wizard(step+1));bind();}
function prepareExport(){const button=document.querySelector('#prepareExport');button.disabled=true;document.querySelector('#exportStatus').textContent='Preparing export…';setTimeout(()=>{document.querySelector('#exportStatus').innerHTML='<p>Download ready</p><a id="exportDownload" href="/export.csv">Download CSV</a>';},150);}
document.querySelector('#areaProjects').addEventListener('click',home);document.querySelector('#areaReports').addEventListener('click',()=>document.querySelector('#openReports').click());document.querySelector('#areaSettings').addEventListener('click',()=>document.querySelector('#showDuplicate').click());bind();
</script></body></html>`;
export function createExplorerFixture(){return http.createServer((req,res)=>{if(req.url==='/export.csv'){res.writeHead(200,{'Content-Type':'text/csv; charset=utf-8','Content-Disposition':'attachment; filename="fixture-export.csv"'});res.end('record_id,status\nsynthetic-001,ready\n');return;}res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'});res.end(html);});}
